steps.script:
var ov = tree.root.get_node("/root/TutorialOverlay")
var wt = tree.root.get_node_or_null("/root/Main/HUD_Right/VBoxContainer/ShootingScrollContainer/ShootingPanel/DeclarationBox/WeaponTree")
if wt == null:
	return "no weapon tree"
if not ov._anchor_ok:
	return "anchor never resolved"
if not ov._anchor_rect.is_equal_approx(wt.get_global_rect()):
	return "spotlight is not on the weapon tree: %s vs %s" % [str(ov._anchor_rect), str(wt.get_global_rect())]
var panel: Rect2 = tree.root.get_node("/root/Main/HUD_Right").get_global_rect()
if ov._anchor_rect.size.x < panel.size.x - 20.0:
	return "weapon tree no longer fills the panel (%s in %s) — the clamp assertions below would prove nothing" % [str(ov._anchor_rect), str(panel)]
return "ok"
